// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llamacppimport com.roshan.persona.brain.llm.provider.FinishReasonimport com.roshan.persona.brain.llm.provider.GenerationConfigimport com.roshan.persona.brain.llm.provider.GenerationResultimport com.roshan.persona.brain.llm.provider.LocalLlmProviderimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.common.AppErrorimport timber.log.Timberimport java.lang.ref.Cleaner/** * NOUS — Llama.cpp local LLM provider (v2.1). * * Implements [LocalLlmProvider] using llama.cpp via JNI. * * ## v2.1 Features *   - mmap memory mapping (prevents OOM) *   - Zero-copy token streaming (token IDs, NOT strings) *   - Barge-in via `g_should_stop` C++ flag *   - Cleaner for guaranteed native memory cleanup *   - Battery saver throttle (CPU-only: max_tokens=100) *   - KV cache context shifting *   - LoRA adapter hot-swapping *   - Lookahead decoding support * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§4 Local LLM</a> */class LlamaCppProvider(    private val modelPath: String,    override val modelId: String,    override val contextLength: Int,    override val modelSizeBytes: Long,    private val useGpu: Boolean,    private val useMmap: Boolean = true,    private val lookaheadConfig: LookaheadDecodingConfig = LookaheadDecodingConfig(),) : LocalLlmProvider {    @Volatile    private var modelHandle: Long = 0L    @Volatile    private var loraHandle: Long = 0L    // v2.1: Vocabulary loaded once at model load (for zero-copy token decoding)    private var vocabulary: Map<Int, String>? = null    // v2.1: Cleaner for guaranteed native memory cleanup    private val cleaner = Cleaner.create()    override val isLoaded: Boolean get() = modelHandle != 0L    override val availableVramMb: Int get() = if (useGpu) VulkanConfig.getVramMb() else 0    override suspend fun load(): Result<Unit> {        if (isLoaded) {            Timber.tag("NOUS.L4").v("Model already loaded: %s".format(modelId))            return com.roshan.persona.common.Result.Success(Unit, CorrelationId.generate(), 0)        }        if (!LlamaCppJni.ensureLoaded()) {            Timber.tag("NOUS.L4").w("Native library not available — cannot load model")            return com.roshan.persona.common.Result.Failure(                error = AppError.Llm.ModelMissing(modelId),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val startNanos = System.nanoTime()        modelHandle = LlamaCppJni.nativeLoadModel(modelPath, contextLength, useGpu, useMmap)        if (modelHandle == 0L) {            Timber.tag("NOUS.L4").e("Failed to load model: %s".format(modelId))            return com.roshan.persona.common.Result.Failure(                error = AppError.Llm.ModelLoadFailed(modelId),                correlationId = CorrelationId.generate(),                durationNanos = System.nanoTime() - startNanos,            )        }        // v2.1: Register cleaner for automatic cleanup (prevents VRAM leak on app kill)        cleaner.register(this, NativeModelCleaner(modelHandle))        // v2.1: Load vocabulary for zero-copy token decoding        loadVocabulary()        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        Timber.tag("NOUS.L4").i("Model loaded: %s in %dms (GPU=%s, mmap=%s)".format(modelId, durationMs, useGpu, useMmap))        return com.roshan.persona.common.Result.Success(Unit, CorrelationId.generate(), System.nanoTime() - startNanos)    }    override suspend fun unload(): Result<Unit> {        if (modelHandle != 0L) {            // Remove LoRA adapter first            if (loraHandle != 0L) {                LlamaCppJni.nativeRemoveLoraAdapter(modelHandle, loraHandle)                loraHandle = 0L            }            LlamaCppJni.nativeUnload(modelHandle)            Timber.tag("NOUS.L4").i("Model unloaded: %s".format(modelId))            modelHandle = 0L        }        vocabulary = null        return com.roshan.persona.common.Result.Success(Unit, CorrelationId.generate(), 0)    }    override suspend fun generate(        prompt: String,        config: GenerationConfig,        onToken: (String) -> Unit,    ): Result<GenerationResult> {        if (!isLoaded) {            return com.roshan.persona.common.Result.Failure(                error = AppError.Llm.ModelMissing(modelId),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val startNanos = System.nanoTime()        // v2.1: Battery saver throttle (CPU-only → max_tokens=100)        val effectiveConfig = if (!useGpu) {            config.copy(maxTokens = minOf(config.maxTokens, BATTERY_SAVER_MAX_TOKENS))        } else {            config        }        // v2.1: Check context overflow before generation (context shifting)        LlamaCppJni.nativeCheckContextOverflow(modelHandle, contextLength)        // v2.1: Zero-copy token callback (token IDs, NOT strings)        val tokenCallback = object : LlamaCppJni.TokenCallback {            override fun onTokenId(tokenId: Int) {                // Decode token ID to string in Kotlin (NOT JNI) — zero GC pressure                val text = vocabulary?.get(tokenId) ?: ""                if (text.isNotEmpty()) {                    onToken(text)                }            }            override fun shouldStop(): Boolean = false        }        // Generate        val fullText = LlamaCppJni.nativeGenerate(            modelHandle,            prompt,            effectiveConfig.maxTokens,            effectiveConfig.temperature,            effectiveConfig.topP,            effectiveConfig.topK,            effectiveConfig.repeatPenalty,            tokenCallback,        )        val durationNanos = System.nanoTime() - startNanos        val durationMs = durationNanos / 1_000_000        val tokensGenerated = estimateTokens(fullText)        val tps = if (durationMs > 0) tokensGenerated.toFloat() / (durationMs / 1000f) else 0f        Timber.tag("NOUS.L4").v(            "Generated %d tokens in %dms (%.1f tps)", tokensGenerated, durationMs, tps        )        return com.roshan.persona.common.Result.Success(            data = GenerationResult(                text = fullText,                tokensGenerated = tokensGenerated,                tokensPerSecond = tps,                durationMs = durationMs,                finishReason = FinishReason.STOP,                promptTokens = estimateTokens(prompt),                modelId = modelId,            ),            correlationId = CorrelationId.generate(),            durationNanos = durationNanos,        )    }    override suspend fun embed(text: String): Result<FloatArray> {        if (!isLoaded) {            return com.roshan.persona.common.Result.Failure(                error = AppError.Llm.ModelMissing(modelId),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val startNanos = System.nanoTime()        val embedding = LlamaCppJni.nativeEmbed(modelHandle, text)        if (embedding.isEmpty()) {            return com.roshan.persona.common.Result.Failure(                error = AppError.Llm.ModelLoadFailed(modelId),                correlationId = CorrelationId.generate(),                durationNanos = System.nanoTime() - startNanos,            )        }        return com.roshan.persona.common.Result.Success(            data = embedding,            correlationId = CorrelationId.generate(),            durationNanos = System.nanoTime() - startNanos,        )    }    // ─── v2.1: Barge-in ───────────────────────────────────────────    /**     * Stop generation immediately (v2.1 barge-in at C++ level).     *     * Sets `g_should_stop` atomic flag — C++ loop checks every token.     * Stops within 1 token (< 50ms).     */    fun stopGeneration() {        LlamaCppJni.nativeStopGeneration()        Timber.tag("NOUS.L4").i("Generation stopped (barge-in)")    }    // ─── v2.1: LoRA hot-swap ──────────────────────────────────────    /**     * Hot-swap persona LoRA adapter without reloading base model.     *     * @param loraPath path to .gguf LoRA file (~20MB)     * @return true if successful     */    suspend fun swapPersona(loraPath: String): Boolean {        if (!isLoaded) return false        val oldHandle = loraHandle        val newHandle = LlamaCppJni.nativeLoadLoraAdapter(modelHandle, loraPath, 1.0f)        if (newHandle == 0L) {            Timber.tag("NOUS.L4").w("Failed to load LoRA adapter: %s".format(loraPath))            return false        }        if (oldHandle != 0L) {            LlamaCppJni.nativeRemoveLoraAdapter(modelHandle, oldHandle)        }        loraHandle = newHandle        Timber.tag("NOUS.L4").i("LoRA adapter swapped: %s".format(loraPath))        return true    }    // ─── v2.1: Vulkan context recovery ────────────────────────────    /**     * Check if Vulkan context is valid after returning from background.     *     * @return true if context is valid, false if model needs reload     */    fun isContextValid(): Boolean {        if (!useGpu) return true      // CPU-only = always valid (no context needed)        if (!isLoaded) return false   // GPU mode but not loaded = invalid        return VulkanConfig.isContextValid(modelHandle)    }    // ─── Internal helpers ─────────────────────────────────────────    /**     * v2.1: Load vocabulary for zero-copy token decoding.     *     * Loads all token ID → text mappings once at model load.     * This avoids JNI string allocation during generation (zero GC pressure).     */    private fun loadVocabulary() {        if (modelHandle == 0L) return        val vocabSize = LlamaCppJni.nativeGetVocabSize(modelHandle)        if (vocabSize == 0) {            Timber.tag("NOUS.L4").w("Vocabulary size is 0 — zero-copy disabled")            return        }        val vocab = mutableMapOf<Int, String>()        for (tokenId in 0 until minOf(vocabSize, MAX_VOCAB_SIZE)) {            val text = LlamaCppJni.nativeGetTokenText(modelHandle, tokenId)            if (text != null && text.isNotEmpty()) {                vocab[tokenId] = text            }        }        vocabulary = vocab        Timber.tag("NOUS.L4").v("Vocabulary loaded: %d tokens".format(vocab.size))    }    /**     * Estimate token count (heuristic: 4 chars ≈ 1 token).     */    private fun estimateTokens(text: String): Int {        if (text.isEmpty()) return 0        return ((text.length + 3) / 4).coerceAtLeast(1)    }    /**     * v2.1: Cleaner for guaranteed native memory cleanup.     *     * If the OS kills the app, `unload()` might never be called.     * This Cleaner ensures `nativeUnload()` is called when the provider     * is garbage collected, preventing VRAM/RAM leaks.     */    private class NativeModelCleaner(        private val handle: Long,    ) : Runnable {        override fun run() {            if (handle != 0L) {                try {                    LlamaCppJni.nativeUnload(handle)                    Timber.tag("NOUS.L4").i("Native model cleaned up via Cleaner (handle=%d)".format(handle))                } catch (e: Throwable) {                    // Ignore — process is shutting down                }            }        }    }    companion object {        /** v2.1: Battery saver — max tokens for CPU-only inference. */        const val BATTERY_SAVER_MAX_TOKENS = 100        /** Max vocabulary size to load (safety cap). */        const val MAX_VOCAB_SIZE = 128_000    }}/** * v2.1: Lookahead decoding configuration. * * Uses Jacobi iterations to predict multiple future tokens within a * single forward pass of the SAME model. No draft model needed. */data class LookaheadDecodingConfig(    val enabled: Boolean = false,    val lookaheadTokens: Int = 4,    val jacobiIterations: Int = 2,)